<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';require_login();$code=trim($_GET['code']??'');$s=$pdo->prepare('SELECT * FROM orders WHERE order_code=? AND user_id=?');$s->execute([$code,$_SESSION['user']['id']]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Order not found.');}$s=$pdo->prepare('SELECT * FROM order_status_log WHERE order_id=? ORDER BY created_at');$s->execute([$order['id']]);$logs=$s->fetchAll();$pageTitle='Order Tracking';include __DIR__.'/../includes/partials/header.php';?><h1>Track <?=e($order['order_code'])?></h1><p>Status: <strong><?=e($order['status'])?></strong></p><div class="tracking-timeline"><?php foreach($logs as $l):?><div class="tracking-step"><strong><?=e(ucwords(str_replace('_',' ',$l['status'])))?></strong><small><?=e($l['created_at'])?></small><p><?=e($l['note'])?></p></div><?php endforeach;?></div><?php include __DIR__.'/../includes/partials/footer.php';?>